#!/bin/bash
m=$(( 0xFFFFFFFF << (32 - $2) & 0xFFFFFFFF )); IFS='.' read -ra ip <<< "$1"; n0=$(( ip[0] & (m >> 24) )); n1=$(( ip[1] & (m >> 16 & 255) )); n2=$(( ip[2] & (m >> 8 & 255) )); n3=$(( ip[3] & (m & 255) )); b0=$(( n0 | (~(m >> 24) & 255) )); b1=$(( n1 | (~(m >> 16) & 255) )); b2=$(( n2 | (~(m >> 8) & 255) )); b3=$(( n3 | (~m & 255) )); echo "$n0.$n1.$n2.$(( n3 + 1 )) - $b0.$b1.$b2.$(( b3 - 1 ))"
